import { readFileSync, writeFileSync } from 'node:fs'

const files = readFileSync(process.argv[2], 'utf8').trim().split('\n')
for (const file of files) {
  const lines = readFileSync(file, 'utf8').split('\n')
  let changed = 0
  const out = lines.map((line) => {
    if (line.includes('deniedReadRoots')) return line
    if (!/\bworkspaceRoot\b/.test(line)) return line
    if (!/\bmode\b/.test(line)) return line
    // Shorthand property form: `{ mode, workspaceRoot }`
    if (/\bworkspaceRoot\s*[,}]/.test(line) && !/workspaceRoot\s*:/.test(line)) {
      changed += 1
      return line.replace(/\bworkspaceRoot\b/, 'workspaceRoot, deniedReadRoots: []')
    }
    const match = /workspaceRoot:\s*/.exec(line)
    if (match === null) return line
    // Scan the value expression, honouring nesting and quotes, to find where it ends.
    let index = match.index + match[0].length
    let depth = 0
    let quote = ''
    for (; index < line.length; index += 1) {
      const ch = line[index]
      if (quote !== '') {
        if (ch === '\\') index += 1
        else if (ch === quote) quote = ''
        continue
      }
      if (ch === "'" || ch === '"' || ch === '`') { quote = ch; continue }
      if (ch === '(' || ch === '[' || ch === '{') { depth += 1; continue }
      if (ch === ')' || ch === ']' || ch === '}') {
        if (depth === 0) break
        depth -= 1
        continue
      }
      if (ch === ',' && depth === 0) break
    }
    let end = index
    while (end > 0 && /\s/.test(line[end - 1])) end -= 1
    changed += 1
    return `${line.slice(0, end)}, deniedReadRoots: []${line.slice(end)}`
  })
  if (changed > 0) writeFileSync(file, out.join('\n'))
  console.log(`${file}: ${changed}`)
}

