      state: 'unenforced',
      reason: 'the deployment sandbox mode is danger-full-access, which runs commands unconfined',
    })
  })

  it('records that a composition without a sandbox policy resolves no denied directories', async () => {
    const { ctx } = await registered(() => {}, { withPolicy: false })
    expect(entryOf(ctx)).toEqual({
      capability: 'shell',
