/** Test-only producer: one keyless task whose single check is a shell command over the workspace. */

import type { Context } from '@deepseek-ai/cordis'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { EnvironmentDefinition } from '@deepseek-ai/dsh-environments'
import { CheckId } from '@deepseek-ai/dsh-verification'

declare module '@deepseek-ai/dsh-environments/types' {
  interface EnvironmentKindMap {
    /** A keyless task whose check runs one shell command; no kind-specific detail. */
    'process-smoke': Record<string, never>
  }
}

export const name = 'register-environment'
export const inject = ['environments']

const definition: EnvironmentDefinition<'process-smoke'> = {
  id: EnvironmentId('smoke:confined-marker'),
  kind: 'process-smoke',
  name: 'smoke:confined-marker',
  description: 'The workspace holds MARKER.',
  task: {
    prompt: 'Create a file named MARKER in the workspace.',
  },
  checks: [{ id: CheckId('marker-file'), outcome: 'the workspace holds MARKER', run: 'test -f MARKER' }],
  heldOut: false,
  owner: 'headless-agent read-barrier-process fixture',
  provenance: 'curated',
  detail: {},
}

/**
 * Register the environment under the producer's own fiber.
 * @param ctx - the plugin context carrying the environment registry.
 */
export function apply(ctx: Context): void {
  ctx.effect(() => ctx.environments.register(definition))
}

/**
 * Keyless adapter that plays an implementer which first tries to read the
 * validator's standard through the shell and then does the task it was given.
 * One bash call carries both, so a single transcript records what the confined
 * process could reach.
 */

import type { Context } from '@deepseek-ai/cordis'
import {
  CallId,
  LlmAdapter,
  type GenerateOptions,
  type LlmResolvedModelInfo,
  type StreamChunk,
} from '@deepseek-ai/dsh-llm'
import type {} from '@deepseek-ai/dsh-read-barrier'

/** What the tool result says when the confined shell could read the reserved standard. */
export const LEAKED_MARKER = 'STANDARD-LEAKED'

/** What the tool result says when it could not. */
export const DENIED_MARKER = 'STANDARD-DENIED'

/**
 * The one command the implementer runs: read every reserved standard the
 * barrier root holds, report which way that went, then satisfy the check.
 * @param root - the barrier root the deployment resolved.
 * @returns the shell source, whose exit status is always zero.
 */
export function probeCommand(root: string): string {
  return `if cat ${root}/runs/*/standard.json > leaked.txt 2>/dev/null; then echo ${LEAKED_MARKER}; else echo ${DENIED_MARKER}; fi; touch MARKER`
}

class ProcessMockAdapter extends LlmAdapter {
  constructor(private readonly root: string) {
    super()
  }

  override async resolveModel(provider: string, model: string): Promise<LlmResolvedModelInfo> {
    return { provider, id: model, name: model }
  }

  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const last = options.messages.at(-1)
    if ((last?.content ?? []).some(block => block.type === 'tool-result')) {
      yield * reply('TASK COMPLETE')
      return
    }
    const args = JSON.stringify({
      command: probeCommand(this.root),
      description: 'Read the standard, then create MARKER.',
    })
    yield { type: 'block-start', index: 0, blockType: 'tool-call' }
    yield { type: 'tool-call-delta', index: 0, id: CallId('probe-call'), name: 'bash', argumentsDelta: args }
    yield { type: 'block-end', index: 0, block: { type: 'tool-call', id: CallId('probe-call'), name: 'bash', arguments: args } }
    yield { type: 'usage', usage: { inputTokens: 17, outputTokens: 5 } }
    yield { type: 'finish', reason: { kind: 'tool-calls' } }
  }
}

/** One text answer as the canonical block sequence of a stopped step. */
function * reply(text: string): Generator<StreamChunk> {
  yield { type: 'block-start', index: 0, blockType: 'text' }
  yield { type: 'text-delta', index: 0, text }
  yield { type: 'block-end', index: 0, block: { type: 'text', text } }
  yield { type: 'usage', usage: { inputTokens: 23, outputTokens: 2 } }
  yield { type: 'finish', reason: { kind: 'stop' } }
}

export const name = 'process-mock-llm'

/** The barrier supplies the root the scripted command targets, so nothing guesses a path. */
export const inject = ['llm', 'readBarrier']

/**
 * Register the keyless `process-mock` adapter.
 * @param ctx - the plugin context carrying the LLM runtime and the barrier.
 */
export function apply(ctx: Context): void {
  ctx.llm.registerAdapter(['process-mock'], new ProcessMockAdapter(ctx.readBarrier.root))
}

#!/usr/bin/env node
/**
 * Test driver: boot the read-barrier-process composition and run the registered
 * environment, which claims `isolation: process`. It reports one `result` record
 * carrying what the confined shell reached, the enforcement census the barrier
 * recorded, and either the run's certificate or the refusal that stopped it —
 * the two outcomes this host can produce, decided by whether a sandbox backend
 * here can express a denied read root.
 */

import { mkdir, readFile } from 'node:fs/promises'
import { join } from 'node:path'
import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import { HarnessError } from '@deepseek-ai/dsh-llm'
import type { ReadBarrierEnforcementEntry } from '@deepseek-ai/dsh-read-barrier'
import type { SessionEvent } from '@deepseek-ai/dsh-session'

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('read-barrier-process driver requires a config path')

/** Read one workspace file, answering the empty string when the run never created it. */
async function readIfPresent(path: string): Promise<string> {
  try {
    return await readFile(path, 'utf8')
  } catch {
    // Absent is the expected outcome for the leak file: the confined `cat`
    // wrote nothing, so its redirect left an empty file or none at all.
    return ''
  }
}

const ctx = await boot('read-barrier-process-e2e', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; the runner creates its agent only over the settled application.
  await ctx.get('loader')?.await()
  const runner = ctx.get('environmentRuns')
  const barrier = ctx.get('readBarrier')
  if (runner === undefined || barrier === undefined) {
    throw new Error('read-barrier-process driver requires the runner and the barrier')
  }
  const workspace = join(process.cwd(), 'workspace')
  await mkdir(workspace)

  const toolOutputs: string[] = []
  let scope: { enforcement: readonly ReadBarrierEnforcementEntry[] } | undefined
  const stopStreaming = ctx.on('session/event', (_session, event: SessionEvent) => {
    if (event.type === 'read-barrier/scope') scope = event.data
    if (event.type !== 'tool/result') return
    const blocks = event.data.message.content
    for (const block of blocks) {
      for (const part of block.content) {
        if (part.type === 'text') toolOutputs.push(part.text)
      }
    }
  }, { global: true })

  let certified = false
  let isolation: string | undefined
  let refusal: { code: string; message: string } | undefined
  try {
    const report = await runner.run({ environment: EnvironmentId('smoke:confined-marker'), workspace })
    certified = report.certified
    isolation = report.certificate?.isolation
  } catch (error: unknown) {
    // The claim failing is the OTHER admissible outcome: a host whose backends
    // cannot express the denial must refuse the claim, not the barrier.
    if (!(error instanceof HarnessError)) throw error
    refusal = { code: error.code, message: error.message }
  }
  stopStreaming()

  process.stdout.write(`${JSON.stringify({
    type: 'result',
    root: barrier.root,
    certified,
    ...isolation === undefined ? {} : { isolation },
    ...refusal === undefined ? {} : { refusal },
    enforcement: scope?.enforcement ?? [],
    toolOutputs,
    leaked: await readIfPresent(join(workspace, 'leaked.txt')),
    marker: await readIfPresent(join(workspace, 'MARKER')) !== undefined,
  })}\n`)
} finally {
  await ctx.fiber.dispose()
}

