/** Why an executor whose composition has no sandbox policy denies nothing. */
const NO_POLICY = 'no ctx.sandboxPolicy is composed, so the executor resolves no denied directories'

/** Why an executor running under the unconfining mode denies nothing. */
const FULL_ACCESS = 'the deployment sandbox mode is danger-full-access, which runs commands unconfined'

 * The probe carries the barrier's own root as the denied directory: it always
 * exists and is always denied to an implementer, so a backend that can express
 * it can express every other directory the barrier collects. The registration
 * is scoped to the barrier's availability, so unloading either plugin unwinds
 * the claim with it.
 *
 * @param ctx - the executor's plugin context; the barrier and the policy are
 *   both read optionally, because an executor composes without either.
 * @param capability - the path-opening capability this executor provides.
 * @param wrap - performs one representative confinement under the probe policy;
 *   it must throw exactly when this host cannot confine that policy, which is
 *   what the executor's own calls would do.
 */
export function enforceReadBarrier(
  ctx: Context,
  capability: ReadBarrierEnforcedCapability,
  wrap: (policy: SandboxPolicy) => void,
): void {
  // Loader siblings mount concurrently, so the barrier may arrive after this
  // executor; `inject` runs the registration when it does and unwinds with it.
  ctx.inject(['readBarrier'], (scope: Context) => {
    const barrier = scope.readBarrier
    const policy = scope.get('sandboxPolicy')?.resolve()
    if (policy === undefined) {
      barrier.cannotEnforce(capability, NO_POLICY)
      return
    }
    if (policy.mode === 'danger-full-access') {
      barrier.cannotEnforce(capability, FULL_ACCESS)
      return
    }
    try {
      wrap({ ...policy, mode: policy.mode, deniedReadRoots: [barrier.root] })
    } catch (error: unknown) {
      barrier.cannotEnforce(capability, error instanceof Error ? error.message : String(error))
      return
    }
    barrier.enforce(capability)
  })
}

