/**
 * Mirror the source-location lines a generator refreshed in an English catalog
 * into its Chinese twin: the twin carries the same `packages/...:<line>` links,
 * so each old spelling maps to the new one wherever it appears.
 */
import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'

const pairs = [
  ['docs/persistence-catalog.md', 'docs/persistence-catalog.zh.md'],
  ['docs/event-producer-consumer.md', 'docs/event-producer-consumer.zh.md'],
  ['docs/config-catalog.md', 'docs/config-catalog.zh.md'],
]

/** Every `path:line` token in one text, mapped from its path to the set of lines. */
function locations(text) {
  const found = new Map()
  for (const match of text.matchAll(/`((?:packages|native|scripts)\/[^`:]+):(\d+)`/g)) {
    const [, path, line] = match
    if (!found.has(path)) found.set(path, new Set())
    found.get(path).add(Number(line))
  }
  return found
}

for (const [english, chinese] of pairs) {
  const before = execFileSync('git', ['show', `HEAD:${english}`], { encoding: 'utf8' })
  const after = readFileSync(english, 'utf8')
  const oldLocs = locations(before)
  const newLocs = locations(after)
  const renames = []
  for (const [path, oldLines] of oldLocs) {
    const newLines = newLocs.get(path) ?? new Set()
    const removed = [...oldLines].filter(line => !newLines.has(line)).sort((a, b) => a - b)
    const added = [...newLines].filter(line => !oldLines.has(line)).sort((a, b) => a - b)
    if (removed.length !== added.length) {
      console.log(`SKIP ${path}: ${removed.length} removed vs ${added.length} added`)
      continue
    }
    for (const [index, from] of removed.entries()) renames.push([path, from, added[index]])
  }
  let text = readFileSync(chinese, 'utf8')
  let applied = 0
  for (const [path, from, to] of renames) {
    const token = `\`${path}:${from}\``
    if (!text.includes(token)) continue
    text = text.replaceAll(token, `\`${path}:${to}\``)
    applied += 1
  }
  writeFileSync(chinese, text)
  console.log(`${chinese}: ${applied}/${renames.length} location(s) mirrored`)
}

